import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.DaCm-iTo.js";const h=JSON.parse('{"title":"EmakiCoreLib","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/corelib/index.md","filePath":"en/modules/corelib/index.md","lastUpdated":null}'),r={name:"en/modules/corelib/index.md"};function s(n,e,d,l,c,m){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="emakicorelib" tabindex="-1">EmakiCoreLib <a class="header-anchor" href="#emakicorelib" aria-label="Permalink to &quot;EmakiCoreLib&quot;">​</a></h1><p>EmakiCoreLib is the shared runtime core for every Emaki Series business plugin. It does not provide a full gameplay loop by itself. Instead, it provides cross-plugin foundations: actions, GUI templates, item-source resolution, PDC helpers, item assembly, conditions, expressions, economy bridges, weighted random utilities, scheduler compatibility, and shared bStats runtime.</p><blockquote><p>Sectioning rule: this page documents capabilities that all plugins can reuse. Actions, APIs, configuration fields, and gameplay flows that are registered by Attribute, Forge, Strengthen, Cooking, Gem, Skills, Item, or Level belong to the corresponding plugin documentation.</p></blockquote><h2 id="basic-information" tabindex="-1">Basic information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Version</td><td><code>4.6.9</code></td></tr><tr><td>API jar</td><td><code>emaki-corelib-api-4.6.9.jar</code></td></tr><tr><td>Runtime plugin jar</td><td><code>EmakiCoreLib-4.6.9.jar</code></td></tr><tr><td>Main class</td><td><code>emaki.jiuwu.craft.corelib.EmakiCoreLibPlugin</code></td></tr><tr><td>Java</td><td><code>25</code></td></tr><tr><td>Paper API</td><td><code>1.21.8-R0.1-SNAPSHOT</code></td></tr><tr><td>paper-plugin.yml api-version</td><td><code>1.21.8</code></td></tr><tr><td>folia-supported</td><td><code>true</code></td></tr><tr><td>Hard dependencies</td><td>None</td></tr><tr><td>Soft dependencies</td><td>Vault, ExcellentEconomy, PlaceholderAPI, MMOItems, MythicMobs, ItemsAdder, Nexo, Oraxen, EcoItems, NeigeItems, CraftEngine, PacketEvents</td></tr><tr><td>Main command</td><td><code>/emakicorelib</code> (aliases <code>/corelib</code>, <code>/emakicore</code>)</td></tr><tr><td>Permissions</td><td><code>emakicorelib.admin</code>, <code>emakicorelib.reload</code></td></tr></tbody></table><p>CoreLib must load first. Business plugins depend on its shared services. If CoreLib fails to start, fix CoreLib before debugging other modules.</p><h2 id="runtime-compatibility" tabindex="-1">Runtime compatibility <a class="header-anchor" href="#runtime-compatibility" aria-label="Permalink to &quot;Runtime compatibility&quot;">​</a></h2><p>CoreLib emits a compatibility report during startup. Missing Java 25 or Paper/Folia capabilities prevent startup; Minecraft versions below <code>1.21.8</code>, unknown versions, and <code>1.22.0</code> or newer are reported as unverified with warnings rather than being rejected through a guessed version allowlist. Dependent plugins can read this report through <code>EmakiCoreLibApi.compatibilityReport()</code>.</p><h2 id="installation-boundary" tabindex="-1">Installation boundary <a class="header-anchor" href="#installation-boundary" aria-label="Permalink to &quot;Installation boundary&quot;">​</a></h2><p>Install only runtime plugin jars on the server:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/</span></span>
<span class="line"><span>├── EmakiCoreLib-4.6.9.jar</span></span>
<span class="line"><span>└── EmakiAttribute-4.6.9.jar / EmakiForge-4.6.4.jar / ...</span></span></code></pre></div><p>Do not put <code>emaki-corelib-api-*.jar</code> into the server <code>plugins/</code> directory. API jars are for third-party developers as Maven <code>provided</code> or Gradle <code>compileOnly</code> dependencies.</p><h2 id="what-corelib-provides" tabindex="-1">What CoreLib provides <a class="header-anchor" href="#what-corelib-provides" aria-label="Permalink to &quot;What CoreLib provides&quot;">​</a></h2><h3 id="shared-action-system" tabindex="-1">Shared action system <a class="header-anchor" href="#shared-action-system" aria-label="Permalink to &quot;Shared action system&quot;">​</a></h3><p>The action system lets plugins run messages, sounds, particles, commands, economy operations, experience operations, temporary items, blocks, teleporting, and action templates from YAML. See <a href="./actions.html">Actions</a> for syntax, control prefixes, CoreLib built-in actions, and the <code>/corelib action list|run</code> admin command.</p><p>Business plugins may append their own actions to the same registry. Level exp actions, Attribute stat actions, and Skills skill actions are documented on their own plugin pages instead of being centralized here.</p><h3 id="gui-system" tabindex="-1">GUI system <a class="header-anchor" href="#gui-system" aria-label="Permalink to &quot;GUI system&quot;">​</a></h3><p>The GUI system provides menu templates, slot parsing, buttons, click handling, sessions, item-source resolution, and dynamic rendering foundations. Business plugins declare their own GUI files and runtime flows. See <a href="./gui.html">GUI</a>.</p><h3 id="item-source" tabindex="-1">Item Source <a class="header-anchor" href="#item-source" aria-label="Permalink to &quot;Item Source&quot;">​</a></h3><p>The Item Source system resolves Vanilla, CraftEngine, ItemsAdder, Nexo, Oraxen, EcoItems, MMOItems, NeigeItems, EmakiItem, and other item providers so recipes, materials, rewards, and GUI slots can use stable IDs instead of display names or lore. See <a href="./item-source.html">Item Source</a>.</p><h3 id="pdc-and-item-assembly" tabindex="-1">PDC and item assembly <a class="header-anchor" href="#pdc-and-item-assembly" aria-label="Permalink to &quot;PDC and item assembly&quot;">​</a></h3><p>CoreLib wraps Bukkit PersistentDataContainer and uses Assembly to merge layers written by different modules into the final item name and lore. Forge, Strengthen, Gem, Item, Attribute, and other modules use this chain to avoid overwriting each other. See <a href="./pdc.html">PDC</a>, <a href="./assembly.html">Assembly</a>, and <a href="./structured-presentation.html">Name &amp; Lore Operations</a>.</p><h3 id="shared-gameplay-events" tabindex="-1">Shared gameplay events <a class="header-anchor" href="#shared-gameplay-events" aria-label="Permalink to &quot;Shared gameplay events&quot;">​</a></h3><p>CoreLib normalizes selected Bukkit / MythicMobs gameplay events into configuration event IDs reused by EmakiLevel experience sources and EmakiCodex advancement triggers. See <a href="./gameplay-events.html">Gameplay Event IDs</a> for usable IDs and variables.</p><h3 id="conditions-expressions-economy-and-weights" tabindex="-1">Conditions, expressions, economy, and weights <a class="header-anchor" href="#conditions-expressions-economy-and-weights" aria-label="Permalink to &quot;Conditions, expressions, economy, and weights&quot;">​</a></h3><ul><li><a href="./condition.html">Condition</a>: shared condition expressions and condition groups.</li><li><a href="./expression.html">Expression</a>: formulas for cost, chance, level, damage, and configuration values.</li><li><a href="./economy.html">Economy</a>: Vault / ExcellentEconomy providers and dynamic provider enumeration.</li><li><a href="./weight.html">Weight</a>: reusable tools for random pools, quality pools, reward pools, and pity systems.</li></ul><h2 id="recommended-reading-order" tabindex="-1">Recommended reading order <a class="header-anchor" href="#recommended-reading-order" aria-label="Permalink to &quot;Recommended reading order&quot;">​</a></h2><h3 id="server-owners-configuration-maintainers" tabindex="-1">Server owners / configuration maintainers <a class="header-anchor" href="#server-owners-configuration-maintainers" aria-label="Permalink to &quot;Server owners / configuration maintainers&quot;">​</a></h3><ol><li><a href="./item-source.html">Item Source</a>: learn how to reference materials and rewards reliably.</li><li><a href="./actions.html">Actions</a>: learn success/failure/reward/feedback calls.</li><li><a href="./condition.html">Condition</a>: configure permission, item, state, and expression checks.</li><li><a href="./expression.html">Expression</a>: write cost, chance, and numeric formulas.</li><li><a href="./gui.html">GUI</a>: adjust menu layout and button behavior.</li><li>The corresponding business plugin pages for actual gameplay configuration.</li></ol><h3 id="third-party-developers" tabindex="-1">Third-party developers <a class="header-anchor" href="#third-party-developers" aria-label="Permalink to &quot;Third-party developers&quot;">​</a></h3><ol><li><a href="./pdc.html">PDC</a>: understand shared data boundaries.</li><li><a href="./assembly.html">Assembly</a>: understand multi-module presentation merging.</li><li>The corresponding plugin API pages: call public APIs, not implementation classes.</li></ol><h2 id="default-runtime-folder" tabindex="-1">Default runtime folder <a class="header-anchor" href="#default-runtime-folder" aria-label="Permalink to &quot;Default runtime folder&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiCoreLib/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>└── lang/</span></span>
<span class="line"><span>    ├── zh_CN.yml</span></span>
<span class="line"><span>    └── en_US.yml</span></span></code></pre></div><p><code>config.yml</code> controls language, the GUI backend, shared gameplay events, action loops and action templates, and global Debug. Setting <code>debug.global_all</code> to <code>true</code> enables Debug output for every Emaki module that uses CoreLib&#39;s <code>DebugLogger</code>. Administrators can also toggle it temporarily with <code>/corelib debug all on|off|status</code>; a CoreLib reload restores the configured value. <code>lang/</code> stores CoreLib messages. Business plugins generate their own folders; do not mix business configuration into CoreLib unless that page explicitly says so.</p>`,34)])])}const u=a(r,[["render",s]]);export{h as __pageData,u as default};
